<template>
  <div class="row">
    <q-btn
      round
      color="positive"
      icon="done"
      size="xs"
      class="q-mr-sm"
      @click="
        $event.stopPropagation();
        doneBtnClicked();
      "
    />
    <q-btn
      round
      color="red-5"
      icon="close"
      size="xs"
      @click="
        $event.stopPropagation();
        errorBtnClicked();
      "
    />
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import sessionHelper from 'src/utils/sessionHelper';
import { approvalInfoStatus } from 'src/constants';
import { useFormBuilderStore, useDocumentStore } from 'src/store/main';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
    elementIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: ['inputClicked', 'updateModel'],
  mixins: [sessionHelper],

  computed: {},
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },

  methods: {
    doneBtnClicked() {
      if (this.isFormBuilderMode) {
        return;
      }

      this.handleApprovalInfo(approvalInfoStatus.approved);
    },
    errorBtnClicked() {
      if (this.isFormBuilderMode) {
        return;
      }
      this.handleApprovalInfo(approvalInfoStatus.rejected);
    },
    handleApprovalInfo(status: string) {
      const poChargeFieldName =
        this.formLayout[this.groupIndex][this.elementIndex - 2].name;
      const lineChargeFieldName =
        this.formLayout[this.groupIndex][this.elementIndex - 1].name;

      delete this.formBuilderModel[lineChargeFieldName].input_error;

      const approvalInfoParam = {
        status: status,
        currentUserId: this.getLoggedinUserId(),
        currentDateTime: Date.now(),
        lineFieldValue: Number(
          this.formBuilderModel[lineChargeFieldName].value,
        ),
        poFieldValue: Number(this.formBuilderModel[poChargeFieldName].value),
      };

      this.formBuilderModel[lineChargeFieldName]['approval_info'] =
        this.getApprovalInfoObj(approvalInfoParam);
    },
    getApprovalInfoObj(approvalInfoParam: any) {
      const lineFieldValue = approvalInfoParam.lineFieldValue
        ? approvalInfoParam.lineFieldValue
        : 0;
      const poFieldValue = approvalInfoParam.poFieldValue
        ? approvalInfoParam.poFieldValue
        : 0;

      let approvedAmount = 0;
      let rejectedAmount = 0;

      if (approvalInfoParam.status == approvalInfoStatus.approved) {
        approvedAmount = lineFieldValue;
        rejectedAmount = 0;
      }

      if (approvalInfoParam.status == approvalInfoStatus.rejected) {
        approvedAmount = poFieldValue;
        rejectedAmount = lineFieldValue - poFieldValue;
      }

      return {
        approval_required: true,
        approval_status: approvalInfoParam.status,
        approved_or_rejected_by: approvalInfoParam.currentUserId,
        approved_or_rejected_at: approvalInfoParam.currentDateTime,
        approved_amount: approvedAmount,
        rejected_amount: rejectedAmount,
      };
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { fieldErrors, enableExportButton, doctype } = storeToRefs(doc_store);

    const form_builder_store = useFormBuilderStore();
    const {
      formLayout,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
    } = storeToRefs(form_builder_store);
    return {
      doctype,
      formLayout,
      fieldErrors,
      formBuilderModel,
      isFormBuilderMode,
      enableExportButton,
      formBuilderConfigModel,
    };
  },
});
</script>
